function update() {
  if (!release) return;

  // update theta and omega based on equations of motion
  const thetaPrime = omega;
  const omegaPrime = -G / L * Math.sin(theta);

  theta += thetaPrime * dt;
  omega += omegaPrime * dt;

  t += dt;

